/bin/bash -lc "python - <<'PY'
import os,time
from bioblend.galaxy import GalaxyInstance
with open(os.environ['GALAXY_API_KEY_FILE']) as fh:key=fh.read().strip()
gi=GalaxyInstance('https://usegalaxy.org',key)
h='bbd44e69cb8906b5df155e3d4d15c6b2'
updated=0; skipped=0; failed=0
for label,cid in [('animals','15387c92b556ba21'),('fungi','f1a9a56b199efbf1')]:
 els=gi.histories.show_dataset_collection(h,cid).get('elements',[])
 for e in els:
  d=e['object']
  if d.get('file_ext')=='fasta':
   skipped+=1; continue
  ok=False
  for attempt in range(8):
   try:
    gi.histories.update_dataset(h,d['id'],datatype='fasta')
    updated+=1; ok=True
    break
   except Exception as exc:
    if '429' in str(exc) or 'Too Many Requests' in str(exc):
     time.sleep(10)
    else:
     print('FAIL',label,e['element_identifier'],type(exc).__name__,flush=True); break
  if not ok: failed+=1
  time.sleep(0.5)
  if (updated+skipped+failed)%25==0:
   print('PROGRESS',label,'updated',updated,'skipped',skipped,'failed',failed,flush=True)
print('DONE','updated',updated,'skipped',skipped,'failed',failed,flush=True)
PY"

